# Try: expand 7s by 1 neighborhood (all adjacent cells including diagonals)
expanded = set(sevens)
for (r, c) in sevens:
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < 30 and 0 <= nc < 26:
                expanded.add((nr, nc))

print(f"Expanded 7s: {sorted(expanded)}")

